 "content": "def transform(grid):
    out = [row[:] for row in grid]
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        positions = [c for c, v in enumerate(row) if v != background]
        for a, b in zip(positions, positions[1:]):
            if b - a == 2 and row[a + 1] == background:
                out[r][a + 1] = 2
    return out
